    @Test
    void merge_parentNotReleasedOrWithoutModel_returns422() throws Exception {
        String released = "BK-MNR-R-" + unique();
        releasedWithModel(released, "100", "10", "0");

        // 父批未检验（QUARANTINED）→ 422
